checkValidEmailForm({ showErrors = true } = {}) {
  const nameValidity = this.#realName.checkValidity();
  const emailValidity = this.#email.checkValidity();

  this.#realName.setAttribute(
    "aria-invalid",
    !nameValidity && (showErrors || this.#touchedInputs.has(this.#realName))
  );
  this.#email.setAttribute(
    "aria-invalid",
    !emailValidity && (showErrors || this.#touchedInputs.has(this.#email))
  );
  const completed = nameValidity && emailValidity;

this.#currentConfig = {
  realName: this.#realName.value,
  email: this.#email.value,
};

this.#manualConfigButton.classList.toggle("visibility-hidden", !completed);
this.dispatchEvent(
  new CustomEvent("config-updated", {
    bubbles: true,
    detail: { completed },
  })
);

Assert.ok(
  !invalidUpdatedEvent.detail.completed,
  "Event should indicate the form is not complete"
);
Assert.ok(
  BrowserTestUtils.isHidden(manualConfigButton),
  "Manual config button should be hidden"
);
Assert.equal(
  email.ariaInvalid,
  "false",
  "Email should have aria-invalid set to false"
);
Assert.equal(
  realName.ariaInvalid,
  "false",
  "Untouched name should not have aria-invalid set to true"
);
